transfer.sketch:
value Refusal: code, message, path: [label], where, valid: [name], hint?, fix?, hostName?

-- scope = aliases in FROM/JOIN; catalog = information_schema snapshot + query-log frequencies
suggestColumn(name, scope) → Suggestion | none
  -- 1. structural: the name resolves, it just needs qualifying
  hits = [t for t in scope.tables where catalog.has(t, name)]
  if len(hits) > 1: return Suggestion(E_AMBIGUOUS_COLUMN, "it exists on " ++ join(hits, ", "),
                                     hits[0] ++ "." ++ name)
  -- 2. mined from the query log: what analysts and the model actually typed
  if redirects has lower(name):
    return Suggestion(E_UNKNOWN_COLUMN, redirects[name].hint, redirects[name].fix)   -- fix is SQL text
  -- 3. near spelling, searched inside the joined tables first, then the catalog by usage
  c = closest(name, columns(scope.tables) ++ byFrequency(catalog.columns), budget: 1)
  if c: return Suggestion(E_UNKNOWN_COLUMN, "did you mean " ++ c ++ "?", c)
  -- 4. same name, other relation: the column is real, the table is just not joined
  for t in catalog.tables where catalog.has(t, name) and t ∉ scope.tables:
    return Suggestion(E_COLUMN_NOT_IN_FROM, name ++ " lives on " ++ t ++ ", not in this query",
                      "LEFT JOIN " ++ t ++ " ON " ++ t ++ ".id = …")
  return none

suggestFunction(name, dialect) → Suggestion | none
  if redirects[dialect] has name:
    return Suggestion(E_WRONG_DIALECT, redirects[dialect][name].hint, redirects[dialect][name].fix)
  if curatedDialectMap has name:
    return Suggestion(E_WRONG_DIALECT, name ++ " is " ++ dialectOf(name) ++ "; here use …",
                      fix(name, dialect))
  return closest(name, dialect.functions, budget: 1)

-- in use
SELECT amount FROM ord            → E_AMBIGUOUS_COLUMN,          fix "o.amount"
SELECT strftim(ts,'%Y') …         → E_WRONG_DIALECT,             fix "DATE_TRUNC('year', ts)"
SELECT lifetime_value FROM users  → E_COLUMN_NOT_IN_FROM,        fix "JOIN orders o ON …"
